// Each season has 50 distinct ten-question levels, balanced 4/4/2.
selectBank=function(){
 const level=Math.max(1,Math.min(50,Number(chosenLevel)||1));
 const season=BANK.filter(q=>q.s===currentSeason),picked=[];
 for(const [difficulty,count] of [['easy',4],['medium',4],['challenging',2]]){
  picked.push(...season.filter(q=>(q.d==='hard'?'challenging':q.d)===difficulty).slice((level-1)*count,level*count));
 }
 return shuffle(picked.map(q=>{const choices=shuffle(q.o.map((v,i)=>({v,yes:i===q.a})));return {id:q.id,q:q.q,opts:choices.map(c=>c.v),answer:choices.findIndex(c=>c.yes)};}));
};
